def is_correct_option(option_text):
    forbidden_words = ['必定100%', '完全無誤差', '不需要數據', '絕對不會過擬合']
    for word in forbidden_words:
        if word in option_text:
            return False # 1 秒剔除！
    return True

def select_algorithm(has_label, is_continuous, need_speed):
    if not has_label:
        return 'K-Means (非監督分群)'
    else:
        if is_continuous:
            return 'Linear Regression / Ridge / XGBoost Regressor'
        else:
            return 'Logistic Regression (二元) / XGBoost Classifier'

def interpret_p_value(p_val, alpha=0.05):
    if p_val < alpha:
        return "✅ 拒絕 H0：達到統計顯著差異！(Reject H0)"
    else:
        return "❌ 無法拒絕 H0：無顯著差異！(Fail to Reject H0)"

def get_eu_risk_tier(ai_application):
    if ai_application in ['Social Scoring', 'Subliminal Manipulation', 'Public Realtime Biometrics']:
        return '❌ Unacceptable (全面禁止)'
    elif ai_application in ['Medical SaMD', 'HR Resume Screening', 'Credit Scoring', 'Critical Infra']:
        return '⚠️ High Risk (強制事前合規審計)'
    elif ai_application in ['Chatbot', 'Deepfake', 'AI Generated Text']:
        return 'ℹ️ Specific Transparency (必須揭露標籤)'
    else:
        return '✅ Minimal Risk (自由發展)'

